+static void merge_sort_iter(uint32_t* a, uint32_t* tmp, size_t n) {
+    const size_t step = 1;
+    for (size_t size = step; size < n; size *= 2) {
+        for (size_t lo = 0; lo < n; lo += 2 * size) {
+            size_t mid = std::min(lo + size, n);
+            size_t hi = std::min(lo + 2 * size, n);
+            size_t i = lo, j = mid, k = lo;
+            while (i < mid && j < hi) {
+                tmp[k++] = (a[j] < a[i]) ? a[j++] : a[i++];
+            }
+            while (i < mid) tmp[k++] = a[i++];
+            while (j < hi) tmp[k++] = a[j++];
+            for (size_t t = lo; t < hi; ++t) a[t] = tmp[t];
+        }
+    }
